import SwiftUI
struct MoneyCard:View{let title:String;let amount:Decimal;let colour:Color;var body:some View{VStack(alignment:.leading,spacing:6){Text(title).font(.caption).foregroundStyle(.secondary);Text(amount as NSDecimalNumber,format:.currency(code:"GBP")).font(.title2.bold()).minimumScaleFactor(0.7)}.frame(maxWidth:.infinity,alignment:.leading).padding().background(colour.opacity(0.12),in:RoundedRectangle(cornerRadius:16))}}
struct MobileOverviewView:View{@EnvironmentObject var store:BudgetStore;@EnvironmentObject var subscriptions:SubscriptionStore;var body:some View{ScrollView{VStack(spacing:16){Text("Personal Budget").font(.largeTitle.bold()).frame(maxWidth:.infinity,alignment:.leading);LazyVGrid(columns:[GridItem(.flexible()),GridItem(.flexible())]){MoneyCard(title:"Income",amount:store.income,colour:.green);MoneyCard(title:"Spending",amount:store.spending,colour:.red);MoneyCard(title:"Net",amount:store.income-store.spending,colour:.blue);MoneyCard(title:"Annual contracts",amount:subscriptions.contracts.filter{$0.status == .active}.reduce(0){$0+SubscriptionSchedule().annualisedCost($1)},colour:.indigo)};NavigationLink{MobileReviewView()}{Label("\(store.needsReview.count) items need review",systemImage:"checklist").frame(maxWidth:.infinity,alignment:.leading).padding().background(.orange.opacity(0.12),in:RoundedRectangle(cornerRadius:16))};UpcomingContractsView()}.padding()}.navigationTitle("Overview").navigationBarTitleDisplayMode(.inline)}}
struct MobileTransactionsView:View{@EnvironmentObject var store:BudgetStore;@State private var query="";var shown:[Transaction]{query.isEmpty ? store.transactions:store.transactions.filter{$0.merchant.localizedCaseInsensitiveContains(query)||$0.category.localizedCaseInsensitiveContains(query)}};var body:some View{List{ForEach(shown){tx in NavigationLink{MobileTransactionEditor(transaction:tx)}label:{HStack{VStack(alignment:.leading){Text(tx.merchant).font(.headline);Text(tx.category).font(.caption).foregroundStyle(.secondary)};Spacer();Text(tx.amount as NSDecimalNumber,format:.currency(code:"GBP")).foregroundStyle(tx.amount<0 ? .primary:.green)}}.swipeActions{Button(role:.destructive){store.delete(tx)}label:{Label("Delete",systemImage:"trash")}}}}.searchable(text:$query).navigationTitle("Transactions").toolbar{ToolbarItem(placement:.primaryAction){Button(action:store.addTransaction){Image(systemName:"plus")}}}}
struct MobileTransactionEditor:View{@EnvironmentObject var store:BudgetStore;@State var transaction:Transaction;var body:some View{Form{DatePicker("Date",selection:$transaction.date,displayedComponents:.date);TextField("Merchant",text:$transaction.merchant);TextField("Description",text:$transaction.description);TextField("Amount",value:$transaction.amount,format:.number);Picker("Category",selection:$transaction.category){ForEach(FinanceCategories.all,id:\.self){Text($0).tag($0)}};Section("Receipt"){NavigationLink("Scan or review receipt"){MobileReceiptView(transaction:transaction)}}} .navigationTitle("Edit").toolbar{Button("Save"){store.update(transaction)}}}}
struct MobileBudgetsView:View{@EnvironmentObject var store:BudgetStore;@State private var draft:[String:String]=[:];var body:some View{List(FinanceCategories.all.filter{!["Income","Card payment","Internal transfer","Uncategorised"].contains($0)},id:\.self){c in VStack(alignment:.leading){Text(c).bold();HStack{TextField("Monthly limit",text:Binding(get:{draft[c] ?? ""},set:{draft[c]=$0})).keyboardType(.decimalPad);Button("Set"){store.setBudget(category:c,limit:Decimal(string:draft[c] ?? "") ?? 0)}}}}.navigationTitle("Budgets")}}
struct MobileRecurringView:View{@EnvironmentObject var subscriptions:SubscriptionStore;var body:some View{List{NavigationLink("Add contract"){MobileContractEditor(contract:SubscriptionContract(vendor:"",category:.other,startDate:Date(),billingPeriod:.monthly,nextPaymentDueDate:Date(),expectedAmount:0))};ForEach(subscriptions.contracts){c in NavigationLink{MobileContractEditor(contract:c)}label:{VStack(alignment:.leading){Text(c.vendor).font(.headline);Text("Next: \(c.nextPaymentDueDate.formatted(date:.abbreviated,time:.omitted)) · \(c.expectedAmount as NSDecimalNumber,format:.currency(code:c.currency))").font(.caption).foregroundStyle(.secondary)}}}}.navigationTitle("Recurring")}}
struct MobileReviewView:View{@EnvironmentObject var store:BudgetStore;var body:some View{List(store.needsReview){tx in NavigationLink{MobileTransactionEditor(transaction:tx)}label:{VStack(alignment:.leading){Text(tx.merchant).bold();Text(tx.pendingSplitDraft == nil ? "Uncategorised":"Receipt split awaiting approval").font(.caption).foregroundStyle(.orange)}}}.navigationTitle("Review")}}
struct UpcomingContractsView:View{@EnvironmentObject var subscriptions:SubscriptionStore;var body:some View{VStack(alignment:.leading){Text("Upcoming payments").font(.headline);ForEach(SubscriptionTracker().dueSoon(subscriptions.contracts,from:Date(),days:30).prefix(5)){c in HStack{Text(c.vendor);Spacer();Text(c.expectedAmount as NSDecimalNumber,format:.currency(code:c.currency))}.padding(.vertical,4)}}.frame(maxWidth:.infinity,alignment:.leading).padding().background(.thinMaterial,in:RoundedRectangle(cornerRadius:16))}}
struct MobileContractEditor:View{@EnvironmentObject var subscriptions:SubscriptionStore;@Environment(\.dismiss)var dismiss;@State var contract:SubscriptionContract;var body:some View{Form{TextField("Vendor",text:$contract.vendor);Picker("Type",selection:$contract.category){ForEach(SubscriptionCategory.allCases){Text($0.title).tag($0)}};DatePicker("Start date",selection:$contract.startDate,displayedComponents:.date);DatePicker("Next payment",selection:$contract.nextPaymentDueDate,displayedComponents:.date);TextField("Amount",value:$contract.expectedAmount,format:.number).keyboardType(.decimalPad);Picker("Period",selection:$contract.billingPeriod){ForEach(BillingPeriod.allCases){Text($0.title).tag($0)}};Picker("Pricing",selection:$contract.pricing){ForEach(ContractPricing.allCases){Text($0.title).tag($0)}}}.navigationTitle("Contract").toolbar{Button("Save"){subscriptions.save(contract);dismiss()}}}}

}
